const d = $('Buscar Análise e Overrides').item.json;
const tabelas = d.tabelas_pontos || {};
const ov = d.overrides || {};
const det = d.detalhes_calculo || {};

function pontosOpcao(criterio, categoria) {
  const t = tabelas[criterio];
  if (!t) return 0;
  if (categoria in t) return Number(t[categoria]);
  return Number(t['ND'] ?? 0);
}
function pontosBanda(criterio, valor) {
  const t = tabelas[criterio];
  if (!t || !t.bands) return 0;
  if (valor === 'ND' || valor === null || valor === undefined) return Number(t.nd_pontos ?? 0);
  const num = Number(valor);
  if (!Number.isFinite(num)) return Number(t.nd_pontos ?? 0);
  for (const b of t.bands) {
    if (b.max === null || b.max === undefined || num <= b.max) return Number(b.pontos);
  }
  return Number(t.nd_pontos ?? 0);
}
const TIPO_BANDA = new Set(['serasa_score', 'protestos', 'execucoes_relevantes']);

// aplica override na categoria e repontua um bloco (d1/d2/d3)
function repontuar(bloco) {
  const subs = Array.isArray(bloco?.subcriterios) ? bloco.subcriterios : [];
  const novos = subs.map((s) => {
    const o = ov[s.criterio];
    if (!o) return { ...s };
    const cat = TIPO_BANDA.has(s.criterio) ? Number(o.valor_numerico) : o.valor_texto;
    const pontos = TIPO_BANDA.has(s.criterio)
      ? pontosBanda(s.criterio, cat)
      : pontosOpcao(s.criterio, cat);
    return { ...s, categoria: cat, pontos, corrigido_manualmente: true };
  });
  const total = novos.reduce((sum, s) => sum + Number(s.pontos || 0), 0);
  return { bloco: { ...bloco, subcriterios: novos, total }, total };
}

const r1 = repontuar(det.d1);
const r2 = repontuar(det.d2);
const r3 = repontuar(det.d3);

// D4 — usa faturamento corrigido se houver override
const curva = tabelas['dependencia_curva'] || { p0_pct: 2, pmax_pct: 20 };
const valorPago = Number(d.valor_compras_anual || 0);
const fatOverride = ov['faturamento_estimado'] ? Number(ov['faturamento_estimado'].valor_numerico) : null;
const faturamento = Number(fatOverride ?? d.faturamento_estimado ?? 0);
let s4, d4_nd = false, p_pct = null;
if (faturamento > 0) {
  p_pct = (valorPago / faturamento) * 100;
  const p0 = Number(curva.p0_pct ?? 2);
  const pmax = Number(curva.pmax_pct ?? 20);
  s4 = Math.round(100 * Math.max(0, Math.min(1, (pmax - p_pct) / (pmax - p0))) * 100) / 100;
} else {
  s4 = 50; d4_nd = true;
}

// campos_nd: remove o que foi corrigido
const ndAntes = Array.isArray(d.campos_nd) ? d.campos_nd : [];
const camposND = ndAntes.filter((c) => {
  if (c === 'dependencia_faturamento') return d4_nd;
  return !ov[c];
});

const totalCampos = 15;
const completude_pct = Math.round(((totalCampos - camposND.length) / totalCampos) * 10000) / 100;

return [{ json: {
  analise_id: d.analise_id,
  s1_fiscal: r1.total, s2_financeira: r2.total, s3_regime: r3.total, s4_dependencia: s4,
  s5_maturidade: d.s5_maturidade,
  completude_pct, campos_nd: camposND,
  decisao_sobrescrita: d.decisao_sobrescrita === true,
  decisao_atual: d.decisao,
  breakdown: {
    d1: r1.bloco, d2: r2.bloco, d3: r3.bloco,
    d4: {
      valor_compras_anual: valorPago,
      faturamento_estimado_fornecedor: faturamento || null,
      participacao_pct: p_pct !== null ? Math.round(p_pct * 100) / 100 : null,
      nd: d4_nd, pontos: s4,
      corrigido_manualmente: fatOverride != null,
    },
  },
} }];

const dims = $('Repontuar com Overrides').item.json;
const score = $('Executar Calcular Score').item.json;

// se a decisão já foi definida manualmente, ela prevalece sobre o recálculo
const sobrescrita = dims.decisao_sobrescrita === true;

return [{ json: {
  analise_id: dims.analise_id,
  s1_fiscal: dims.s1_fiscal, s2_financeira: dims.s2_financeira,
  s3_regime: dims.s3_regime, s4_dependencia: dims.s4_dependencia,
  s5_maturidade: dims.s5_maturidade,
  completude_pct: dims.completude_pct, campos_nd: dims.campos_nd,
  score_total: score.score_total,
  decisao: sobrescrita ? dims.decisao_atual : score.decisao,
  status: sobrescrita ? 'concluido' : score.status,
  preliminar: score.preliminar,
  versao_pesos_id: score.versao_pesos_id, versao_thresholds_id: score.versao_thresholds_id,
  detalhes_calculo: { ...dims.breakdown, pesos_usados: score.pesos_usados },
} }];

